##### Setup and definition of helper functions for table formatting etc.

library(kableExtra)
library(magrittr)
library(purrr)

# Make landscape orientation for table in PDF
landscape_tab <- function(tab) {
  if(knitr::is_latex_output()) {
    return(kableExtra::landscape(tab))
  } else {
    return(tab)
  }
}

# Reduce vertical space in PDF
reduce_vspace <- function(space = "-0.9cm") {
  if(knitr::is_latex_output()) {
    return(knitr::asis_output(paste0("\\vspace{", space, "}")))
  }
  return(invisible(""))
}

# Change from bold in PDF to bold in HTML for table entries
adjust_bold_html <- function(df, cols = 3:20) {
  
  df[, cols] <- df[, cols] %>%
    purrr::map_dfc(
      function(.x) {
        w <- which(grepl("\\bftab", .x, fixed = TRUE))
        .x_sub <- gsub("\\bftab ", replacement = "",
                       x = .x[w], fixed = TRUE)
        .x[w] <- paste0(
          "<strong>", 
          .x_sub, 
          "</strong>"
        )
        .x
      }
    )
  df
}

adjust_html_tab_size <- function(x) {
  `%>%` <- magrittr::`%>%`
  if (knitr::is_html_output()) {
    x <- x %>% 
      kableExtra::kable_styling(full_width = FALSE) %>%
      kableExtra::scroll_box(width = "100%")
  }
  x
}










