## ----plotsimexamples, fig.cap = "Examples of quarterly simulated series (grey and solid) together with the true underlying trends (blue and dashed) for $n_1$ and the estimated trends (red and solid) using the DeSeaTS framework with $r=3$. All examples are with number of observations $n_1$ and the same simulated errors from $\\{e_{1,t}\\}$.", echo = FALSE, fig.height = 5, fig.pos = "t", fig.align='center'----
library(deseats)
library(magrittr)
library(tidyverse)

set.seed(123) 

### Number of observations

ny <- 15
n1 <- ny * 4

# Time points

t1 <- 1:n1
xt_n1 <- (t1) / n1

### Trend functions

# Trend 1

t1_n1 <- (5 * xt_n1 + 1) %>%
  ts(frequency = 4)

# Trend 2

t2_n1 <- (2.5 * tanh(5 * (xt_n1 - 0.4)) + 3.5) %>%
  ts(frequency = 4)

# Trend 3

t3_n1 <- (3.2 * xt_n1 + 0.92 * (sin(3.2 * pi * (xt_n1 - 0.2))) + 1.85) %>%
  ts(frequency = 4)


### Seasonalities

## Exactly periodic and with frequency 4

quart <- (t1 - 1) %% 4
s1 <- rep(-0.39, length(t1))
s1[quart == 1] <- 0.01
s1[quart == 2] <- -0.04
s1[quart == 3] <- 0.42

s1_n1 <- s1 %>%
  ts(frequency = 4)

#### Slowly changing and with frequency 4
f_sc <- 0.83 * (1  +0.1 * sin(50 * pi * xt_n1 / 9) + 0.2 * cos(3 * pi * xt_n1))
s2_n1 <-  f_sc * s1_n1

### Errors

arma1 <- list(ar = 0.75, sd_e = 0.083)

# Example simulations
e1 <- arima.sim(model = list(ar = arma1$ar), sd = arma1$sd_e, n = n1) %>%
  ts(frequency = 4)

series1s1 <- t1_n1 + s1_n1 + e1
series1s2 <- t1_n1 + s2_n1 + e1
series2s1 <- t2_n1 + s1_n1 + e1
series2s2 <- t2_n1 + s2_n1 + e1
series3s1 <- t3_n1 + s1_n1 + e1
series3s2 <- t3_n1 + s2_n1 + e1

est1s1 <- deseats(series1s1, set_options(order_poly = 3))
est1s2 <- deseats(series1s2, set_options(order_poly = 3))
est2s1 <- deseats(series2s1, set_options(order_poly = 3))
est2s2 <- deseats(series2s2, set_options(order_poly = 3))
est3s1 <- deseats(series3s1, set_options(order_poly = 3))
est3s2 <- deseats(series3s2, set_options(order_poly = 3))

par_old <- par(no.readonly = TRUE)
par(mfrow = c(3, 2), cex.axis = 0.9, cex.lab = 0.9, cex.main = 0.9,
    mar = c(2, 4, 3, 2) + 0.1, oma = c(2, 0, 0, 0))
ts.plot(series1s1, t1_n1, trend(est1s1),
     col = c("grey50", "blue", "red"),
     main = expression(paste(bold("(a) "), italic(g[1]), ", ", italic(s[1]))),
     lty = c(1, 2, 1))
ts.plot(series1s2, t1_n1, trend(est1s2),
