     main = expression(paste(bold("(b) "), italic(g[1]), ", ", italic(s[2]))),
     lty = c(1, 2, 1))
ts.plot(series2s1, t2_n1, trend(est2s1),
     col = c("grey50", "blue", "red"),
     main = expression(paste(bold("(c) "), italic(g[2]), ", ", italic(s[1]))),
     lty = c(1, 2, 1))
ts.plot(series2s2, t2_n1, trend(est2s2),
