## ----echo = FALSE, eval = FALSE, incude = FALSE, purl = TRUE------------------
# 
# ##### Examples for stochastic components for second simulation study


## ----stochexample, echo = FALSE, fig.cap = "A realization of the stochastic trend $G_{2,t}$ and of the stochastic seasonal component $S_{3,t}$ for 15 years.", fig.height = 2.5, fig.width = 5.6, fig.pos = 'h'----
t2_fun <- function(xt) {
  n <- length(xt)
  et <- rnorm(n = n + 200) + 0.05
  
  g_out <- tail(cumsum(et), n)
  (g_out - mean(g_out)) / sd(g_out)
  
}

s3_fun <- function(t, sig2) {
  sig <- sqrt(sig2)
  ps <- 12
  
  n <- length(t)
  m <- 300 * 12
  
  sx <- rep(0, n + m)
  sx[1:11] <- rnorm(n = ps - 1, mean = 0, sd = sig)
  
  for (i in ps:(n + m)) {
    sx[[i]] <- -sum(sx[(i - 11):(i - 1)]) + rnorm(n = 1, mean = 0, sd = sig)
  }
  sx <- tail(sx, n)
  
  (sx - mean(sx)) / sd(sx)
  
  
}

set.seed(1)

n <- 15 * 12
t <- 1:n
xt <- t / n

sig2 <- 0.025

example_trend2 <- ts(t2_fun(xt), frequency = 12)
example_season3 <- ts(s3_fun(t, sig2), frequency = 12)

main1 <- expression(paste(bold("(a) "), italic(G[2*","*t])))
main2 <- expression(paste(bold("(b) "), italic(S[3*","*t])))

par_old <- par(no.readonly = TRUE)
par(mfrow = c(1, 2), cex = 0.6, mar = c(5, 3, 4, 1) + 0.1)
plot(example_trend2, main = main1, ylab = "")
plot(example_season3, main = main2, ylab = "")
par(par_old)


