# 
# ##### Boxplot figures for first simulation study


## -----------------------------------------------------------------------------
unwrap <- function() {
  `%>%` <- magrittr::`%>%`
  data_bw <- read.csv("sim-data/sim1_all_bwidths.csv", check.names = FALSE) %>%
    tidyr::pivot_longer(
      cols = 1:288, 
      names_to = "Setting",
      values_to = "bwidth"
    ) %>%
    separate_wider_delim(
      cols = "Setting",
      delim = "_",
      names = c("N_Year", "Seasonal_Period", "Trend", "Season", "Error_Process",
                "r", "infr")
    ) %>%
    mutate(
      N_Year = as.numeric(N_Year),
      Seasonal_Period = as.numeric(Seasonal_Period),
      infr = factor(infr, levels = c("opt", "nai"))
    ) %>%
    arrange(Seasonal_Period, Error_Process, Season, Trend, r, N_Year, infr) %>%
    group_by(Seasonal_Period, Error_Process, r) %>%
    group_split()
  nams <- map_chr(data_bw, function(.x) {
    
    paste0("sp", .x$Seasonal_Period[[1]], "_r", .x$r[[1]], "_", .x$Error_Process[[1]])
  })
  names(data_bw) <- nams
  data_bw <- data_bw %>%
    map(function(.x) {
      .x %>%
        select(-Error_Process, -r)
    })
}

boxplot_fun <- function(df, ep, poly_ord) {
  parold <- par(no.readonly = TRUE)
  par(mfrow = c(6, 2), mar = c(4, 4, 3, 2) + 0.1)
  on.exit(expr = {par(parold)}, add = TRUE, after = TRUE)

  season_p <- df$Seasonal_Period[[1]]

  df %>%
    mutate(N_Year = factor(N_Year)) %>%
    mutate(infr = factor(infr, levels = c("opt", "nai"))) %>%
    arrange(Trend, Season, N_Year, infr) %>%
    group_by(Season, Trend, infr) %>%
    group_split() %>%
    walk(function(.x, ep, poly_ord, season_p) {
      tn <- switch(
        .x$Trend[[1]],
        "t1" = 1,
        "t2" = 2,
        "t3" = 3
      )
      sn <- switch(
        .x$Season[[1]],
        "s1" = 1,
        "s2" = 2
      )
      ifr <- switch(
        as.character(.x$infr[[1]]),
        "opt" = "optimal",
        "nai" = "naive"
      )

      arma_list <- if (ep == 1) {
        list(ar = 0.75, ma = NULL, sd_e = 0.083)
      } else if (ep == 2) {
        list(ar = c(1.05, -0.3), ma = NULL, sd_e = 0.06)
      }

      cb <- if (poly_ord == 1) {0.05} else if (poly_ord == 3) {0.1}

      if (tn == 1) {
        bw1 <- bw2 <- bw3 <- 0.49
      } else if (tn == 2) {
        fun <- expression(2.5 * tanh(5 * (x - 0.4)) + 3.5)
        bw1 <- hA_calc(fun, arma = arma_list, p = poly_ord, mu = 1, frequ = season_p, n = season_p * 15, cb = cb)$hA
        bw2 <- hA_calc(fun, arma = arma_list, p = poly_ord, mu = 1, frequ = season_p, n = season_p * 30, cb = cb)$hA
        bw3 <- hA_calc(fun, arma = arma_list, p = poly_ord, mu = 1, frequ = season_p, n = season_p * 60, cb = cb)$hA
      } else if (tn == 3) {
        fun <- expression(3.2 * x + 0.92 * (sin(3.2 * pi * (x - 0.2))) + 1.85)
        bw1 <- hA_calc(fun, arma = arma_list, p = poly_ord, mu = 1, frequ = season_p, n = season_p * 15, cb = cb)$hA
        bw2 <- hA_calc(fun, arma = arma_list, p = poly_ord, mu = 1, frequ = season_p, n = season_p * 30, cb = cb)$hA
        bw3 <- hA_calc(fun, arma = arma_list, p = poly_ord, mu = 1, frequ = season_p, n = season_p * 60, cb = cb)$hA
      }

      y_min <- min(bw1, bw2, bw3, .x$bwidth)
      y_max <- max(bw1, bw2, bw3, .x$bwidth)
      ylim <- c(y_min, y_max)

      boxplot(bwidth ~ N_Year, data = .x, xlab = "Number of years",
              ylab = "Estimated bandwidth", ylim = ylim, col = "white",
              main = substitute(italic(g[trn])*", "*italic(s[srn])*", "*infl*" inflation rate", list(trn = tn, srn = sn, infl = ifr)))
      points(c(1, 2, 3), c(bw1, bw2, bw3), pch = 4, col = "red", cex = 1.5)
    }, ep = ep, poly_ord = poly_ord, season_p = season_p)
}

# Get and unwrap data from the file 
# "sim1_all_bwidths.csv"
data_bw <- unwrap()


## ----sim1fig1, fig.cap = "Boxplots of estimated bandwidths using $r=1$ for simulated quarterly data with $\\{e_{1,t}\\}$. Red crosses mark the true $h_A$.", fig.align='center', fig.height = 8.8, fig.width = 5.8, echo = FALSE, fig.pos="H"----
boxplot_fun(data_bw$sp4_r1_e1, ep = 1, poly_ord = 1)


